    (message) => message.client_message_id === attempt.clientMessageId,
  )
  state.value = {
    ...state.value,
    messages: existing
      ? state.value.messages
      : [...state.value.messages, createUserMessage(attempt.text, attempt.clientMessageId)],
    streaming: true,
    runId: null,
    runStatus: 'queued',
    pendingApprovalIds: [],
    pendingApprovalId: null,
    finishReason: null,
    error: null,
    recovery: null,
    usage: null,
    currentAssistantId: null,
    process: [],
    lastSeq: 0,
  }

