    try {
      info.value = await systemApi.info()
      loaded.value = true
    } catch (cause) {
      error.value = errorMessage(cause)
    } finally {
      loading.value = false
    }
  }

  return {
    info,
    loading,
    loaded,
    error,
    models,
    reasoningEfforts,
    capabilities,
    limits,
    defaultModel,
    defaultReasoningEffort,
