  let refreshPromise: Promise<AuthTokens> | null = null

  async function refreshOnce(): Promise<AuthTokens> {
    if (!refreshPromise) {
      refreshPromise = refresh().finally(() => {
        refreshPromise = null
      })
    }
    return refreshPromise
  }

  function handleUnauthorized(): void {
    storage.clearTokens()
    options.onUnauthorized?.()
    if (!options.onUnauthorized) {
      unauthorizedHandler?.()
    }
  }

  client.interceptors.request.use((config) => {
    requestStartedAt.set(config, performance.now())
    const token = storage.getAccessToken()
    if (token) {
      config.headers.set('Authorization', `Bearer ${token}`)
    }
    return config
  })

  client.interceptors.response.use(
    (response) => {
      recordOutcome(response.config, response.status, response.headers)
      return response
    },
    async (error: unknown) => {
      const failed = toApiRequestError(error)
      if (axios.isAxiosError(error)) {
        recordOutcome(error.config, error.response?.status ?? 0, error.response?.headers)
      }
      try {
        const record = {
          code: failed.code,
          message: failed.message,
          requestId: failed.requestId,
          at: Date.now(),
        }
        recordError(record)
        reportError(record)
      } catch {
        // 诊断写入失败不影响业务错误处理。
      }
      if (!isUnauthorized(error)) {
        throw failed
      }

      const config = error.config as RetryableConfig | undefined
      const isRefreshRequest = config?.url?.includes('/auth/refresh')

      if (!config || config._retry || isRefreshRequest) {
        handleUnauthorized()
        throw toApiRequestError(error)
      }

      config._retry = true
      try {
        await refreshOnce()
        return await client.request(config)
      } catch {
        handleUnauthorized()
        throw new ApiRequestError('登录已过期，请重新登录', {
          code: 'unauthorized',
          status: 401,
        })
      }
    },
  )

  return client
}

